<html lang="en">
<meta charset="utf-8">
<title>Walk Anyway</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  * { box-sizing: border-box }
  body {
    margin: 0; min-height: 100vh; background: #080b10;
    display: grid; place-items: center; color: white;
    font-family: system-ui, sans-serif;
  }
  main { width: min(100vw, 1100px); text-align: center }
  canvas { width: 100%; aspect-ratio: 16/9; display: block; background: black }
  button {
    margin: 18px; padding: 12px 28px; border: 1px solid #777;
    border-radius: 5px; color: white; background: #18212b;
    font: inherit; cursor: pointer;
  }
  p { color: #aeb7c2; font-size: 13px; padding: 0 15px }
</style>
<main>
  <canvas id="film" width="960" height="540"
    aria-label="Walk Anyway, a thirty-second animated short"></canvas>
  <button id="play">Play Walk Anyway</button>
  <p>30 seconds · 16:9 · Rain and one spoken line · No music</p>
</main>
<script>
const canvas = document.getElementById('film');
const c = canvas.getContext('2d');
const button = document.getElementById('play');
const W = 960, H = 540;
let start = 0, playing = false, spoken = false, sound, rain, volume;
let smile = 0;

function rect(x,y,w,h,color) {
  c.fillStyle=color; c.fillRect(x,y,w,h);
}
function ellipse(x,y,rx,ry,color) {
  c.fillStyle=color; c.beginPath();
  c.ellipse(x,y,rx,ry,0,0,Math.PI*2); c.fill();
}
function path(points,color) {
  c.fillStyle=color; c.beginPath();
  points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));
  c.closePath(); c.fill();
}
function line(x,y,X,Y,color,width=2) {
  c.strokeStyle=color; c.lineWidth=width; c.beginPath();
  c.moveTo(x,y); c.lineTo(X,Y); c.stroke();
}
function title() {
  rect(0,0,W,H,'#000');
  c.fillStyle='#fff'; c.textAlign='center';
  c.font='500 48px Arial, sans-serif';
  c.fillText('WALK ANYWAY',480,287);
}
function background(t) {
  const sky=c.createLinearGradient(0,0,0,H);
  sky.addColorStop(0,'#08111e'); sky.addColorStop(1,'#263d49');
  c.fillStyle=sky; c.fillRect(0,0,W,H);
  for(let i=0;i<12;i++) {
    const x=i*91-20, h=100+(i*43)%140;
    rect(x,330-h,76,h,'#101d2b');
    for(let j=0;j<3;j++)
      rect(x+13+j*20,350-h,5,9,i%3?'#293e4b':'#776b49');
  }
  rect(0,385,W,155,'#162631');
  path([[0,430],[960,400],[960,540],[0,540]],'#243b47');
  const glow=c.createRadialGradient(465,265,10,465,265,290);
  glow.addColorStop(0,'rgba(246,201,126,.16)');
  glow.addColorStop(1,'rgba(246,201,126,0)');
  c.fillStyle=glow; c.fillRect(0,0,W,H);
  // A single shelter remains the same through every shot.
  rect(270,166,315,12,'#0a131e');
  rect(288,178,7,218,'#6f7e80');
  rect(565,178,7,218,'#6f7e80');
  rect(300,183,260,182,'rgba(118,157,168,.10)');
  rect(302,180,256,4,'#e0bf80');
  rect(313,342,224,9,'#27363d');
  rect(326,351,5,45,'#18262d');
  rect(518,351,5,45,'#18262d');
  rect(222,158,5,241,'#819096');
  rect(205,151,40,48,'#d0d4cd');
  rect(210,158,30,24,'#294252');
  for(let i=0;i<30;i++) {
    const x=(i*137)%960, y=408+(i*29)%125;
    const shimmer=.2+.15*Math.sin(t*2+i);
    line(x,y,x+20+(i%5)*8,y,`rgba(174,190,179,${shimmer})`,1);
  }
}
function umbrella(x,y,s) {
  c.save(); c.translate(x,y); c.scale(s,s);
  line(0,-185,0,-50,'#9ca5a8',2);
  c.strokeStyle='#9ca5a8'; c.lineWidth=3; c.beginPath();
  c.arc(-6,-50,6,0,Math.PI); c.stroke();
  path([[-103,-184],[-87,-207],[-61,-229],[-30,-242],
    [0,-247],[32,-242],[64,-229],[89,-208],[105,-184],
    [70,-190],[36,-183],[0,-190],[-36,-183],[-70,-190]],'#090e17');
  line(-100,-184,0,-247,'#29333e',1);
  line(0,-247,100,-184,'#29333e',1);
  line(0,-247,0,-190,'#29333e',1);
  ellipse(0,-250,2,5,'#161e27');
  c.restore();
}
function person(x,y,s,who,back=false,walk=0) {
  const woman=who==='woman';
  const coat=woman?'#b72e3d':'#395b47';
  const head=woman?-175:-164;
  c.save(); c.translate(x,y); c.scale(s,s);
  const swing=Math.sin(walk)*7;
  // Legs and footwear.
  line(-12,-46,-15+swing,-8,'#17212b',11);
  line(12,-46,15-swing,-8,'#17212b',11);
  if(woman) {
    rect(-24+swing,-24,16,24,'#e1b838');
    rect(8-swing,-24,16,24,'#e1b838');
    rect(-25+swing,-8,24,8,'#f0c447');
    rect(7-swing,-8,25,8,'#f0c447');
  } else {
    ellipse(-16+swing,-5,14,5,'#0b1118');
    ellipse(17-swing,-5,14,5,'#0b1118');
  }
  path([[-23,head+29],[22,head+29],[34,-43],[-34,-43]],coat);
  line(0,head+40,0,-48,woman?'#df5962':'#64806a',1);
  line(-22,head+45,-33,-80,coat,13);
  line(22,head+45,30,-82,coat,13);
  ellipse(-33,-77,5,7,'#c8a899');
  ellipse(30,-79,5,7,'#c8a899');
  rect(-6,head+18,12,18,'#c8a899');
  ellipse(0,head,22,27,'#c8a899');
  if(woman) {
    // Silver bob: same silhouette and colour in every view.
    ellipse(0,head-8,25,24,'#c9d1d8');
    if(!back) {
      ellipse(1,head+3,17,20,'#d8b7a7');
      path([[-24,head-7],[-10,head-28],[20,head-18],
        [8,head-12],[-9,head-8],[-17,head+20],[-24,head+21]],'#d9dfe3');
      rect(18,head-8,7,29,'#bbc6cf');
    } else rect(-23,head-5,46,26,'#c9d1d8');
  } else {
    path([[-21,head-6],[-19,head-20],[-10,head-27],
      [12,head-26],[22,head-12],[19,head-5],
      [10,head-17],[-9,head-17]],'#8d999f');
    if(!back) {
      path([[-19,head+4],[-12,head+27],[0,head+33],
        [15,head+23],[20,head+3],[8,head+12],
        [-4,head+13]],'#bbc1c2');
    }
  }
  if(!back) {
    ellipse(-7,head+1,1.8,1.4,'#253039');
    ellipse(8,head+1,1.8,1.4,'#253039');
    if(woman && smile>0) {
      c.strokeStyle='#8f5554'; c.lineWidth=1.6;
      c.beginPath(); c.arc(1,head+9,6,0.15,Math.PI-0.15); c.stroke();
    } else line(-3,head+13,5,head+13,'#825955',1);
  }
  c.restore();
}
function rainfall(t) {
  c.save(); c.strokeStyle='rgba(178,205,220,.38)'; c.lineWidth=1;
  c.beginPath();
  for(let i=0;i<250;i++) {
    const x=((i*173.31+t*58)%1040)-40;
    const y=((i*83.73+t*(330+i%80))%620)-40;
    c.moveTo(x,y); c.lineTo(x-5,y+16);
  }
  c.stroke(); c.restore();
  rect(0,0,W,25,'rgba(0,0,0,.28)');
  rect(0,H-25,W,25,'rgba(0,0,0,.28)');
}
function speak() {
  if(!('speechSynthesis' in window)) return;
  const u=new SpeechSynthesisUtterance('You came back.');
  u.lang='en-US'; u.rate=.78; u.pitch=.72; u.volume=.95;
  const voices=speechSynthesis.getVoices();
  u.voice=voices.find(v=>/David|George|Daniel|James|Mark/i.test(v.name))
    || voices.find(v=>v.lang.startsWith('en')) || null;
  speechSynthesis.speak(u);
}
async function startRain() {
  const Audio=window.AudioContext||window.webkitAudioContext;
  if(!Audio) return;
  sound=sound||new Audio();
  await sound.resume();
  const b=sound.createBuffer(1,sound.sampleRate*4,sound.sampleRate);
  const d=b.getChannelData(0);
  for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*.55;
  rain=sound.createBufferSource(); rain.buffer=b; rain.loop=true;
  const filter=sound.createBiquadFilter();
  filter.type='lowpass'; filter.frequency.value=2600;
  volume=sound.createGain(); volume.gain.value=0;
  rain.connect(filter); filter.connect(volume); volume.connect(sound.destination);
  rain.start();
}
function draw(t) {
  if(t<2 || t>=28) {
    title();
    if(volume) volume.gain.value=0;
    return;
  }
  if(volume) volume.gain.value=t>=16 && t<21 ? .12 : .25;
  background(t); smile=0;
  if(t<9) {
    person(437,434,1,'woman');
  } else if(t<16) {
    const p=Math.min(1,(t-9)/5.4);
    const x=800-285*p;
    person(437,434,1,'woman');
    person(x,434,.96,'man',false,p<1?(t-9)*7:0);
    umbrella(x-12,434,.97);
  } else if(t<21) {
    // A hard cut into an intimate close two-shot.
    background(t);
    rect(0,0,W,H,'rgba(5,12,20,.3)');
    smile=t>18?1:0;
    person(392,650,2.25,'woman');
    person(568,650,2.16,'man');
    umbrella(488,650,2.2);
    if(!spoken) { spoken=true; speak(); }
  } else {
    const p=(t-21)/7;
    const s=1-.38*p, y=434-65*p, x=480+38*p;
    person(x-36*s,y,s,'woman',true,(t-21)*6);
    person(x+36*s,y,s*.96,'man',true,(t-21)*6+.5);
    umbrella(x+6*s,y,s*1.03);
  }
  rainfall(t);
}
function frame(now) {
  if(!playing) return;
  const t=Math.min(30,(now-start)/1000);
  draw(t);
  if(t<30) requestAnimationFrame(frame);
  else {
    playing=false; title();
    if(rain) { rain.stop(); rain=null; }
    button.disabled=false; button.textContent='Replay Walk Anyway';
  }
}
button.onclick=async()=>{
  if(playing) return;
  button.disabled=true;
  if('speechSynthesis' in window) speechSynthesis.cancel();
  spoken=false;
  try { await startRain(); } catch(e) {}
  playing=true; start=performance.now();
  requestAnimationFrame(frame);
};
if('speechSynthesis' in window) speechSynthesis.getVoices();
title();
